// Themes: iTerm2 colour schemes, mapped onto the deck's tokens.
//
// themes.json is generated by scripts/gen-themes.py from iTerm2's own presets
// and from mbadolato/iTerm2-Color-Schemes. Each entry carries a finished token
// map, so switching is one pass of setProperty and nothing has to be worked
// out in the browser.
//
// The chosen theme's tokens are kept in localStorage, not just its name: a
// small inline script in each page's <head> applies them before first paint,
// so the deck never flashes the stock colours on the way to yours. This file
// is only needed for the picker and for following a change made in the other
// tab.

const KEY_NAME = 'agents.theme';
const KEY_TOKENS = 'agents.themeTokens';
export const DEFAULT_THEME = 'agents deck';

let catalogue = null;

export function applyTheme(t) {
  const r = document.documentElement;
  for (const [k, v] of Object.entries(t.tokens)) r.style.setProperty(k, v);
  r.style.colorScheme = t.light ? 'light' : 'dark';
}

export function savedThemeName() {
  try { return localStorage.getItem(KEY_NAME) || DEFAULT_THEME; } catch { return DEFAULT_THEME; }
}

export function setTheme(t) {
  applyTheme(t);
  try {
    localStorage.setItem(KEY_NAME, t.name);
    // The tokens travel with the name so the next load needs no fetch.
    localStorage.setItem(KEY_TOKENS, JSON.stringify({ name: t.name, light: t.light, tokens: t.tokens }));
  } catch { /* storage unavailable: the theme lasts until this page closes */ }
}

export async function themes() {
  if (!catalogue) {
    const r = await fetch('./themes.json', { cache: 'force-cache' });
    if (!r.ok) throw new Error(`themes.json: http ${r.status}`);
    catalogue = await r.json();
  }
  return catalogue.themes;
}

// A change in one tab reaches the other: Settings and the deck are two pages.
export function followThemeChanges() {
  addEventListener('storage', (e) => {
    if (e.key !== KEY_TOKENS || !e.newValue) return;
    try { applyTheme(JSON.parse(e.newValue)); } catch { /* ignore a bad write */ }
  });
}

// ------------------------------------------------------------------ the picker
const MAX_SHOWN = 120; // 611 of them; the rest wait for a narrower search

// Settings redraws a page by calling a builder and replacing the body, so this
// is synchronous and takes the catalogue the page has already loaded.
export function buildPicker(all, { h, row }) {
  const search = h('input', {
    type: 'search', id: 'theme-q', placeholder: `search ${all.length} themes…`,
    'aria-label': 'search themes', autocomplete: 'off', spellcheck: 'false',
  });
  const only = h('select', { class: 'pick', 'aria-label': 'light or dark' },
    h('option', { value: 'all', text: 'light and dark' }),
    h('option', { value: 'dark', text: 'dark only' }),
    h('option', { value: 'light', text: 'light only' }));
  const count = h('p', { class: 'm' });
  const list = h('div', { class: 'theme-list', role: 'listbox', 'aria-label': 'themes' });

  let current = savedThemeName();

  const themeRow = (t) => {
    const on = t.name === current;
    const chips = h('span', { class: 'theme-chips', 'aria-hidden': 'true' },
      ['--bg', '--panel', '--ink', '--dim', '--accent'].map((k) => {
        const i = h('i', {});
        i.style.background = t.tokens[k];
        return i;
      }));
    const b = h('button', {
      type: 'button', class: `theme-row${on ? ' on' : ''}`, role: 'option',
      'aria-selected': String(on),
    }, chips, h('span', { class: 'theme-name', text: t.name }),
       h('small', { class: 'theme-kind', text: t.light ? 'light' : 'dark' }));
    // Set through the CSSOM, not a style attribute: the page's CSP is
    // style-src 'self', which a style attribute would fall foul of.
    b.style.setProperty('--rbg', t.tokens['--bg']);
    b.style.setProperty('--rink', t.tokens['--ink']);
    b.style.setProperty('--rline', t.tokens['--line']);
    b.addEventListener('click', () => {
      setTheme(t);
      current = t.name;
      for (const el of list.querySelectorAll('.theme-row')) {
        el.classList.remove('on');
        el.setAttribute('aria-selected', 'false');
      }
      b.classList.add('on');
      b.setAttribute('aria-selected', 'true');
    });
    return b;
  };

  function draw() {
    const q = search.value.trim().toLowerCase();
    const kind = only.value;
    const hits = all.filter((t) =>
      (kind === 'all' || (kind === 'light') === !!t.light) &&
      (!q || t.name.toLowerCase().includes(q)));
    list.replaceChildren(...hits.slice(0, MAX_SHOWN).map(themeRow));
    count.textContent = hits.length > MAX_SHOWN
      ? `${hits.length} themes · showing the first ${MAX_SHOWN}, keep typing to narrow it`
      : `${hits.length} theme${hits.length === 1 ? '' : 's'}`;
  }

  search.addEventListener('input', draw);
  only.addEventListener('change', draw);
  draw();

  return [
    row('Theme',
      'Colours come from iTerm2 colour schemes: its own presets, and the set published as mbadolato/iTerm2-Color-Schemes. Only the palette changes; the deck keeps its layout. The choice is remembered in this browser, not on the service, so boards and other computers are unaffected.',
      [h('div', { class: 'theme-ctl' }, search, only)], { tall: true }),
    count,
    list,
  ];
}
